/**
 * GWP V1 wire schema mirrors (architecture §7) — the variant tables are
 * generated from the published `gwp-schema.json` (regenerated by
 * `guiwright-proto::schemadoc`, golden-pinned in Rust AND re-pinned by
 * `test/codec.test.ts` against the copy vendored here).
 *
 * Wire discipline: variants are append-only within the `V1` envelope —
 * `Video` follows `Bye` (M3), the `Window` domain follows `Video`
 * (M6, §16 v0.4 multi-window), the `Gesture` domain follows `Window`
 * (M7, §9 input pipeline), the `Screenshot` domain follows `Gesture`
 * (M10, §7 render domain), the `Snapshot` domain follows `Screenshot`
 * (M11, tree dump) and the `Subscribe` domain follows `Snapshot`
 * (M12, event channel); a mid-enum reorder fails the Rust
 * discriminant pinning test and the schema golden at the same time.
 */

// --- Envelopes ---------------------------------------------------------------

/** Current protocol version (Rust `PROTO_VERSION`, §7). */
export const PROTO_VERSION = 1;

export const GwpRequest = { V1: 0 } as const;
export const GwpResponse = { V1: 0 } as const;
export const GwpEvent = { V1: 0 } as const;

// --- Request variants (index = postcard discriminant) ------------------------

export const RequestV1 = {
  Hello: 0,
  Ping: 1,
  TreeSnapshot: 2,
  Resolve: 3,
  Action: 4,
  Input: 5,
  Clock: 6,
  Mock: 7,
  Inspect: 8,
  Bye: 9,
  Video: 10,
  Window: 11,
  Gesture: 12,
  Screenshot: 13,
  Snapshot: 14,
  Subscribe: 15,
  /** §8.2 set read (M30): the count()/all() enumeration, no timeout. */
  ResolveAll: 16,
  /** §8.3 hit-test read (M32): which node occupies the point, no timeout. */
  HitTest: 17,
  /** §8.1 node-describe read (M36): one node's identity facts, no scope. */
  Describe: 18,
  /** §8.2 set read carrying facts (M39): the describe-all enumeration, no timeout. */
  DescribeAll: 19,
  /** §8.2 set read carrying the description fact (M64): the identity widening, no timeout. */
  DescribeAllIdentity: 20,
  /** §8.1 identity fact set at handle width (M66): the M36 handle pair in, the M64 identity row out — the description fact for one node, no scope, no timeout. */
  DescribeIdentity: 21,
  /** §8.1 identity fact set plus the state facts at handle width (M68): the M36 handle pair in, the M68 identity-state row out — the state three for one node, no scope, no timeout. */
  DescribeIdentityState: 22,
  /** §8.1 state facts at set width (M70): the M64 walk payload in, the M68 identity-state row per match out — the state three for the whole set, one round trip. */
  DescribeAllIdentityState: 23,
} as const;

