export const ResponseV1 = {
  Welcome: 0,
  Pong: 1,
  TreeSnapshot: 2,
  Resolved: 3,
  ActionDone: 4,
  InputQueued: 5,
  ClockState: 6,
  MockDone: 7,
  Codegen: 8,
  Error: 9,
  Bye: 10,
  VideoFile: 11,
  Windows: 12,
  WindowUsed: 13,
  GestureDone: 14,
  Shot: 15,
  TreeDump: 16,
  /** §7 event channel (M12): a pushed event for a subscribed connection. */
  Event: 17,
  /** §7 event channel (M12): the subscription ack. */
  Subscribed: 18,
  /** §8.2 set read (M30): every current match, document order. */
  ResolvedAll: 19,
  /** §8.3 hit-test read (M32): the node under the point, null on a miss. */
  HitTest: 20,
  /** §8.1 node-describe read (M36): the handle's identity facts. */
  Described: 21,
  /** §8.2 set read carrying facts (M39): one Described row per match. */
  DescribedAll: 22,
  /** §8.2 set read carrying the description fact (M64): one identity row per match. */
  DescribedAllIdentity: 23,
  /** §8.1 identity fact set at handle width (M66): the M64 row for the request's handle — the identity four plus the description fact. */
  DescribedIdentity: 24,
  /** §8.1 identity row's state facts at handle width (M68): the M68 row for the request's handle — the identity four, the description fact plus the state three. */
  DescribedIdentityState: 25,
  /** §8.1 identity row's state facts at set width (M70): the M68 row per match, document order — the m64 row-widening rule's fourth link. */
  DescribedAllIdentityState: 26,
} as const;

