// --- Payload types (structs encode fields in declaration order) --------------

export interface TextMatchV1 {
  text: string;
  exact: boolean;
  ignore_case: boolean;
}

export interface VideoOptsV1 {
  /** 0 = the driver default (25 fps). */
  fps: number;
  /** Client-owned artifact dir (Playwright parity); null = driver default. */
  dir: string | null;
}

export interface AdapterInfoV1 {
  name: string;
  framework: string;
  framework_version: string;
  caps: CapsV1;
}

export interface CapsV1 {
  tree_update: boolean;
  logical_snapshot: boolean;
  input: boolean;
  last_frame: boolean;
  render_frame: boolean;
  clock: boolean;
}

export interface Welcome {
  proto_version: number;
  session_id: string;
  tree_seq: number;
  frame_seq: number;
  adapter: AdapterInfoV1;
}

export interface Resolved {
  node: NodeKey;
  generation: number;
  rect: [number, number, number, number] | null;
}

/** §8.2 set read row (M30): one match of a `ResolveAll` — the same facts
 * `Resolved` carries, usable directly as an `action` node. */
export interface ResolvedMatch {
  node: NodeKey;
  generation: number;
  rect: [number, number, number, number] | null;
}

/** §8.1 node-describe row (M36): one node's identity facts — the dump
 * row's facts (role/name/value/bounds), one node instead of a walk. */
export interface DescribedNode {
  node: NodeKey;
  generation: number;
  role: string;
  name: string | null;
  value: string | null;
  bounds: [number, number, number, number] | null;
}

/** §8.2 set-read row carrying the description fact (M64): the
 * `DescribedNode` identity four plus the accessible description — the
 * fact the M38 identity family's third assertion reads (the M39 rows
 * stay byte-pinned; the widening rides its own domain). */
export interface DescribedIdentityNode {
  node: NodeKey;
  generation: number;
  role: string;
  name: string | null;
  value: string | null;
  bounds: [number, number, number, number] | null;
  description: string | null;
}

/** The checked-state fact's wire vocabulary (M68): AccessKit's
 * tri-state beside the not-checkable fact — the m67 record's named
 * standing gap, closed as a four-way word, never squeezed into
 * `boolean | null` (a mixed checkbox is not an unchecked one). */
export type CheckedState = "not_checkable" | "unchecked" | "checked" | "mixed";

/** §8.1 identity row's state facts at handle width (M68): the
 * `DescribedIdentityNode` fields plus the state three — the m67
 * record's named standing gap, closed as the m64 row-widening rule's
 * third link (the M64 rows stay byte-pinned; the widening rides its
 * own domain). */
export interface DescribedIdentityStateNode extends DescribedIdentityNode {
  /** The focused fact: the node IS the tree's focus right now. */
  focused: boolean;
  /** The enabled fact: false = the AccessKit `Disabled` state flag set. */
  enabled: boolean;
  /** The checked tri-state beside the not-checkable fact. */
  checked: CheckedState;
}

export type NodeKey =
  | { kind: "accesskit"; tree: string; node: number }  // tree = 32 hex chars (16 bytes)
  | { kind: "logical"; adapter: string; id: number };

export interface VideoFile {
  path: string;
  frames: number;
  dropped: number;
  duration_ms: number;
}

export interface ClockState {
  virtual_time_ms: number | null;
  paused: boolean;
  steps: number;
}

export interface MockDone {
  id: string;
  detail: string;
}

/** One window target (§16 v0.4): handle = subtree TreeId, or "main". */
export interface WindowInfoV1 {
  handle: string;
  title: string;
  focused: boolean;
}

/** §7 `Shot` (M10): the PNG bytes of the captured frame + provenance. */
export interface Shot {
  frame_seq: number;
  width: number;
  height: number;
  /** PNG-encoded RGBA8 (lossless) — decode with any PNG decoder. */
  png: Uint8Array;
}

/** One `TreeDump` row (M11): identity + the facts viewers render. */
export interface SnapshotNodeV1 {
  key: NodeKey;
  /** AccessKit role `Debug` name (`Button`, …) — the selector vocabulary. */
  role: string;
  name: string | null;
  value: string | null;
  /** Window-relative bounds, physical px. */
  bounds: [number, number, number, number] | null;
  /** Immediate children — DFS order + this count rebuilds the tree. */
  children: number;
}

/** §7 `TreeDump` (M11): the whole logical tree, depth-first per window. */
export interface TreeDump {
  tree_seq: number;
  node_count: number;
  focus: NodeKey | null;
  nodes: SnapshotNodeV1[];
}

// --- Request/response union types --------------------------------------------

export type GwpRequest =
  | { kind: "hello"; proto_version: number; agent: string }
  | { kind: "ping" }
  | { kind: "tree_snapshot" }
  | { kind: "resolve"; selector: Selector; timeout_ms: number }
  | {
      kind: "action";
      node: NodeKey;
      generation: number;
      action: SemAction;
      force: boolean;
      timeout_ms: number;
    }
  | { kind: "input"; events: InputEvent[] }
  | { kind: "clock"; cmd: ClockCmd }
  | { kind: "mock"; cmd: MockCmd }
  | { kind: "inspect"; cmd: InspectCmd }
  | { kind: "bye" }
  | { kind: "video"; cmd: VideoCmd }
  | { kind: "window"; cmd: WindowCmd }
  | { kind: "gesture"; cmd: GestureCmd }
  | { kind: "screenshot"; cmd: ScreenshotCmd }
  | { kind: "snapshot"; cmd: SnapshotCmd }
  | { kind: "subscribe"; cmd: SubscribeCmd }
  | { kind: "resolve_all"; selector: Selector }
  | { kind: "hit_test"; x: number; y: number }
  | { kind: "describe"; node: NodeKey; generation: number }
  | { kind: "describe_all"; selector: Selector }
  | { kind: "describe_all_identity"; selector: Selector }
  | { kind: "describe_identity"; node: NodeKey; generation: number }
  | { kind: "describe_identity_state"; node: NodeKey; generation: number }
  | { kind: "describe_all_identity_state"; selector: Selector };

export type Selector =
  | { kind: "role"; role: string; name: TextMatchV1 | null }
  | { kind: "label"; match: TextMatchV1 }
  | { kind: "text"; match: TextMatchV1 }
  | { kind: "test_id"; id: string }
  | { kind: "value"; match: TextMatchV1 }
  | { kind: "all"; selectors: Selector[] };

export type SemAction =
  | { kind: "click" }
  | { kind: "double_click" }
  | { kind: "set_value"; text: string }
  | { kind: "focus" }
  | { kind: "blur" }
  | { kind: "hover" }
  | { kind: "press"; key: string; modifiers: string[] }
  | { kind: "scroll"; dx: number; dy: number }
  | { kind: "check" }
  | { kind: "uncheck" }
  /** m89: select an option by accessible name on a choice widget. */
  | { kind: "select_option"; option: string }
  /** m90: scroll the node into view (the a11y-first honest form). */
  | { kind: "scroll_into_view_if_needed" };

export type InputEvent =
  | { kind: "pointer_down"; x: number; y: number; button: number }
  | { kind: "pointer_up"; x: number; y: number; button: number }
  | { kind: "pointer_move"; x: number; y: number }
  | { kind: "wheel"; dx: number; dy: number }
  | { kind: "key_down"; key: string; modifiers: string[] }
  | { kind: "key_up"; key: string; modifiers: string[] }
  | { kind: "text_input"; text: string };

export type ClockCmd =
  | { kind: "install_virtual" }
  | { kind: "fast_forward"; ms: number }
  | { kind: "run_for"; ms: number }
  | { kind: "pause" }
  | { kind: "resume" }
  | { kind: "set_time"; ms: number }
  | { kind: "state" };

export type MockCmd =
  | { kind: "install_seam"; id: string; response: string | null }
  | { kind: "clear"; id: string }
  | { kind: "reset_state"; scope: string }
  | { kind: "call"; id: string; scope: string };

export type InspectCmd =
  | { kind: "start_recording" }
  | { kind: "stop_recording" }
  | { kind: "enable_overlay" }
  | { kind: "disable_overlay" }
  | { kind: "highlight"; node: NodeKey | null };

export type VideoCmd =
  | { kind: "start"; opts: VideoOptsV1 }
  | { kind: "stop" };

/** §16 v0.4 multi-window: `Use` aims THIS connection at a window target. */
export type WindowCmd = { kind: "list" } | { kind: "use"; handle: string };

/**
 * §9 gestures (M7): high-level synthetic gestures — the driver
 * synthesizes the raw `InputEvent` batch (per-adapter pacing) and injects
 * it through the target window's real pipeline. Coordinates are logical
 * px relative to the sending connection's active window target.
 */
export type GestureCmd =
  | { kind: "click"; x: number; y: number; button: number; count: number }
  | {
      kind: "drag";
      from_x: number;
      from_y: number;
      to_x: number;
      to_y: number;
      button: number;
    }
  | { kind: "wheel"; dx: number; dy: number }
  | { kind: "key"; key: string; modifiers: string[] }
  | { kind: "type"; text: string };

/**
 * §7 render domain (M10): pull a PNG shot of the session's current frame —
 * the whole window, or the crop of one resolved element (§10 "crop from
 * the window frame by the node's clip-aware rect — never re-render").
 * Element resolution auto-waits `Attached` within `timeout_ms`.
 */
export type ScreenshotCmd =
  | { kind: "window" }
  | { kind: "element"; selector: Selector; timeout_ms: number };

/**
 * §7 tree-dump domain (M11): read the session's whole logical tree as
 * data — the CDP "DOM snapshot" analog. Extensible: new dump forms land
 * behind new variants (append-only discipline).
 */
export type SnapshotCmd =
  | { kind: "full" }
  | { kind: "filtered"; selector: Selector; timeout_ms: number };

/** §7 event channel (M12): turn this connection into a subscriber.
 * `resume` carries the re-attach cursor (the m18 record's named §7
 * follow-on) — the driver replays the coalesced position past it. */
export type SubscribeCmd =
  | { kind: "on"; kinds: EventKind[] }
  | { kind: "off" }
  | { kind: "resume"; kinds: EventKind[]; cursor: ResumeCursor };

/** §7 event kinds (M12): mirrors `EventV1`'s variant order. */
export type EventKind = "tree_changed" | "frame_presented" | "log" | "state_change";

/** §7 server-push event payload (the `events` table vocabulary). */
export type EventV1 =
  | { kind: "tree_changed"; seq: number }
  | { kind: "frame_presented"; seq: number; hash: number }
  | { kind: "log"; record: string }
  | {
      /** A node's checked fact moved (the m20 record's named event): the
       * wire Action path's check vocabulary landed and the tri-state
       * actually moved — the subscription answers instead of a tree
       * poll. */
      kind: "state_change";
      node: NodeKey;
      checked: CheckedState;
    };

export type GwpResponse =
  | ({ kind: "welcome" } & Welcome)
  | { kind: "pong" }
  | { kind: "tree_snapshot"; tree_seq: number; node_count: number }
  | ({ kind: "resolved" } & Resolved)
  | { kind: "action_done"; frame_seq: number; detail: string }
  | { kind: "input_queued"; frame_seq: number }
  | ({ kind: "clock_state" } & ClockState)
  | ({ kind: "mock_done" } & MockDone)
  | { kind: "codegen"; code: string; warnings: string[] }
  | { kind: "error"; code: number; message: string }
  | { kind: "bye" }
  | ({ kind: "video_file" } & VideoFile)
  | { kind: "windows"; windows: WindowInfoV1[] }
  | { kind: "window_used"; handle: string }
  | { kind: "gesture_done"; frame_seq: number; detail: string }
  | ({ kind: "shot" } & Shot)
  | ({ kind: "tree_dump" } & TreeDump)
  | { kind: "event"; event: EventV1 }
  | { kind: "subscribed"; kinds: EventKind[] }
  | { kind: "resolved_all"; matches: ResolvedMatch[] }
  | { kind: "hit_test"; hit: ResolvedMatch | null }
  | ({ kind: "described" } & DescribedNode)
  | { kind: "described_all"; rows: DescribedNode[] }
  | { kind: "described_all_identity"; rows: DescribedIdentityNode[] }
  | ({ kind: "described_identity" } & DescribedIdentityNode)
  | ({ kind: "described_identity_state" } & DescribedIdentityStateNode)
  | { kind: "described_all_identity_state"; rows: DescribedIdentityStateNode[] };
